import Advertise from "../Advertise";
import AdvertiseTemplate from "../AdvertiseTemplate";
export declare type mode = "mobile" | "pc";
export declare type templateType = "FullScreen" | "Banner" | "Popups" | "TextCarousel" | "InsertScreen" | "PcBottomRight" | "Illustration";
export declare type animationName = 'zoom' | 'zoomIn' | 'heartBeat' | 'backInUp' | '';
export interface Animation {
    name: animationName;
    loop?: boolean;
}
export interface AdParam {
    href: string;
    img?: string;
    text?: string;
}
export interface Options {
    template: templateType;
    templateOptions: TemplateOptions;
    created?: (advertise: Advertise, advertiseTemplate: AdvertiseTemplate) => void;
    mounted?: (advertise: Advertise, advertiseTemplate: AdvertiseTemplate) => void;
    destroy?: (advertise: Advertise, advertiseTemplate: AdvertiseTemplate) => void | boolean;
    beforeJump?: (A: HTMLElement, advertise: Advertise, advertiseTemplate: AdvertiseTemplate, link: string) => void;
}
export interface TemplateOptions {
    uid?: string;
    params: Array<AdParam>;
    target?: Element | string;
    title?: string;
    animation?: Animation;
    autoCloseTime?: number;
    insertPosition?: InsertPosition;
    style?: String;
    needAdText?: Boolean;
}
